using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public sealed class LibraryGuide {public string slug="",title="",category="";public int level;}
internal static class GuideLibrary {
 internal static void Validate(Data data){if(data.catalogue==null)data.catalogue=new List<LibraryGuide>();if(data.catalogue.Count>5000||data.catalogue.Any(g=>g==null||!TougliReader.ValidSlug(g.slug)||(g.title??"").Length>500||(g.category??"").Length>300)||data.catalogue.Select(g=>g.slug).Distinct().Count()!=data.catalogue.Count)throw new InvalidDataException("Catalogue de guides invalide.");}
 internal static void Seed(Store store){if(store.Value.catalogue.Count!=0)return;using(var resource=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("Compagnon.Catalogue")){if(resource==null)return;using(var reader=new StreamReader(resource)){var entries=Store.Json.Deserialize<List<LibraryGuide>>(reader.ReadToEnd());var candidate=new Data{catalogue=entries};Validate(candidate);store.Value.catalogue=entries;}}}
 internal static async System.Threading.Tasks.Task<int> Export(string output){try{var items=new List<TougliGuideInfo>();items.AddRange(TougliReader.Catalogue(await CompanionWindow.Download("/api/guide/list",System.Threading.CancellationToken.None)));items.AddRange(GanymedeReader.Catalogue(await CompanionWindow.DownloadAddress(GanymedeReader.Site+"/tree?view=list",System.Threading.CancellationToken.None)));var entries=items.GroupBy(g=>g.Slug).Select(g=>g.First()).Select(g=>new LibraryGuide{slug=g.Slug,title=g.Title,category=g.Category??"",level=g.Level}).ToList();Validate(new Data{catalogue=entries});if(entries.Count<10)throw new IOException("Catalogue incomplet.");Directory.CreateDirectory(Path.GetDirectoryName(output));File.WriteAllText(output,Store.Json.Serialize(entries),new System.Text.UTF8Encoding(false));return 0;}catch(Exception ex){File.WriteAllText(output+".error.txt",ex.ToString());return 1;}}
 internal static List<TougliGuideInfo> Read(Store store){var items=store.Value.catalogue.Select(g=>new TougliGuideInfo{Slug=g.slug,Title=g.title,Category=g.category,Level=g.level}).ToList();foreach(var g in new[]{new TougliGuideInfo{Slug="rsa-rush-sylvestre-accelere",Title="Rush Sylvestre Accéléré"},new TougliGuideInfo{Slug="dofus-sylvestre",Title="Dofus Sylvestre"}})if(!items.Any(x=>x.Slug==g.Slug))items.Add(g);return items.OrderBy(g=>g.Title).ToList();}
 internal static void Merge(Store store,List<TougliGuideInfo> guides){PersonalWorkflows.Change(store,()=>{foreach(var g in guides){store.Value.catalogue.RemoveAll(x=>x.slug==g.Slug);store.Value.catalogue.Add(new LibraryGuide{slug=g.Slug,title=g.Title,category=g.Category??"",level=g.Level});}});}
 internal static IEnumerable<TougliGuideInfo> Filter(IEnumerable<TougliGuideInfo> guides,string query,int source){string key=QuestInstructionIndex.NameKey(query);return guides.Where(g=>(source==0||GanymedeReader.IsGuide(g.Slug)==(source==2))&&(key==""||QuestInstructionIndex.NameKey(g.Title+" "+g.Category).Contains(key)));}
}